header = csv_content.strip().split(';')

eu_mrv_fields = {
    'shipping_total_emissions_co2e': 'M',
    'shipping_fuel_consumption_tonnes': 'M',
    'shipping_voyages_covered_description': 'M',
    'shipping_eu_ports_share_percent': 'M'
}

cdp_fields = {
    'scope1_total_co2e': 'M',
    'scope2_total_location_based_co2e': 'M',
    'emission_reduction_targets_list': 'M',
    'climate_governance_description': 'M',
    'climate_risk_management_process': 'M',
    'climate_scenarios_used': 'M'
}

def generate_row(report_name, fields_map):
    row = [''] * len(header)
    row[0] = report_name
    for field, value in fields_map.items():
        if field in header:
            index = header.index(field)
            row[index] = value
        else:
            print(f"Warning: Field {field} not found in header")
    return ';'.join(row) + ';'

print("EU_MRV ROW:")
print(generate_row('EU_MRV', eu_mrv_fields))
print("\nCDP_DISCLOSURE ROW:")
print(generate_row('CDP_DISCLOSURE', cdp_fields))
